# ------------------------------------------------------------------ scenarios
def scenario_pinned(rng, spec=None):
    """Pinned tasks with simultaneous field, quota, budget and cap edits."""
    spec = spec or rng.choice(TOPOS)
    topo = Topo(spec)
    n, tcount = topo.n, len(topo.foots)
    doms = sorted(set(topo.domains))
    by_dom = {}
    for tid, dom in enumerate(topo.domains):
        by_dom.setdefault(dom, []).append(tid)
    g = rng.randint(1, 4)
    quota = [rng.randint(1, 5) for _ in range(g)]
    budget = [rng.choice([1, 10, 10 ** 12]) for _ in range(g)]
    gkey = [(rng.choice(doms), rng.choice([0, 3])) for _ in range(g)]
    d = rng.randint(1, 25)
    tasks = []
    for tid in range(d):
        gid = rng.randrange(g)
        dom, cls = gkey[gid]
        tasks.append([rng.choice(by_dom[dom]), gid, rng.randint(1, 3), cls, 1 if rng.random() < .6 else 0])
    fp = [set() for _ in range(g)]
    load = [0] * g
    for t in tasks:
        fp[t[1]] |= set(topo.foots[t[0]])
        load[t[1]] += t[2]
    for gid in range(g):
        if load[gid] > quota[gid] * budget[gid]:
            budget[gid] = (load[gid] + quota[gid] - 1) // quota[gid]
    caps = [0] * n
    for gid in range(g):
        for x in fp[gid]:
            caps[x] += quota[gid]
    txs = []
    for _ in range(rng.randint(1, 14)):
        edits = []
        for _ in range(rng.randint(0, 7)):
            kind = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap'])
            if kind in ('move', 'weight', 'class', 'bind', 'pin'):
                tid = rng.randrange(d)
                if kind == 'move':
                    edits.append(['move', tid, rng.randrange(g)])
                elif kind == 'weight':
                    edits.append(['weight', tid, rng.randint(1, 4)])
                elif kind == 'class':
                    edits.append(['class', tid, rng.choice([0, 3, 9])])
                elif kind == 'bind':
                    edits.append(['bind', tid, rng.randrange(tcount)])
                else:
                    edits.append(['pin', tid, rng.randint(0, 1)])
            elif kind == 'quota':
                edits.append(['quota', rng.randrange(g), rng.randint(1, 8)])
            elif kind == 'budget':
                edits.append(['budget', rng.randrange(g), rng.choice([1, 10, 10 ** 12])])
            else:
                edits.append(['cap', rng.randrange(n), rng.randint(0, 200)])
        if rng.random() < 0.35 and d:
            tid = rng.randrange(d)
            edits += [['weight', tid, rng.randint(1, 4)], ['move', tid, rng.randrange(g)],
                      ['pin', tid, rng.randint(0, 1)], ['quota', tasks[tid][1], rng.randint(1, 8)]]
        txs.append({'revision': 0, 'edits': edits,
                    'query': {'groups': [rng.randrange(g) for _ in range(rng.randint(0, 4))],
                              'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 4))],
                              'tasks': [rng.randrange(d) for _ in range(rng.randint(0, 4))]}})
    return {'topology': spec, 'caps': caps, 'groups': [[quota[i], budget[i]] for i in range(g)],
            'tasks': tasks,
            'query': {'groups': list(range(g)), 'nodes': list(range(n)), 'tasks': list(range(d))},
            'transactions': txs}

def scenario_empty(rng, spec=None):
    """No tasks at all: every group is empty no matter what edits do."""
    spec = spec or rng.choice(TOPOS)
    topo = Topo(spec)
    n = topo.n
    g = rng.randint(1, 3)
    return {'topology': spec, 'caps': [rng.randint(0, 3) for _ in range(n)],
            'groups': [[rng.randint(0, 64), rng.choice([1, 10 ** 12])] for _ in range(g)],
            'tasks': [],
            'query': {'groups': list(range(g)), 'nodes': list(range(min(n, 4))), 'tasks': []},
            'transactions': [{'revision': 0, 'edits': [['quota', rng.randrange(g), rng.randint(0, 64)],
                                                        ['budget', rng.randrange(g), 10 ** 12],
                                                        ['cap', rng.randrange(n), rng.randint(0, 5)]],
                              'query': {'groups': list(range(g)), 'nodes': [0], 'tasks': []}}
                             for _ in range(rng.randint(1, 6))]}

def scenario_tight(rng, spec=None):
    """Exactly-fitting capacities and budgets so small edits flip legality."""
    spec = spec or rng.choice(TOPOS)
    topo = Topo(spec)
    n, tcount = topo.n, len(topo.foots)
    doms = sorted(set(topo.domains))
    by_dom = {}
    for tid, dom in enumerate(topo.domains):
        by_dom.setdefault(dom, []).append(tid)
    g = rng.randint(2, 6)
    quota = [rng.choice([1, 2, 64]) for _ in range(g)]
    gkey = [(doms[0], 0) if i % 2 == 0 else (doms[min(1, len(doms) - 1)], 0) for i, d in enumerate(doms)]
    gkey = [(rng.choice(doms), 0) for _ in range(g)]
    d = rng.randint(2, 30)
    tasks = [[rng.choice(by_dom[gkey[rng.randrange(g)][0]]), 0, 1, 0, 0] for _ in range(d)]
    for tid in range(d):
        gid = rng.randrange(g)
        tasks[tid][1] = gid
        tasks[tid][0] = rng.choice(by_dom[gkey[gid][0]])
    load = [0] * g
    for t in tasks:
        load[t[1]] += t[2]
    budget = [max(1, (load[gid] + quota[gid] - 1) // quota[gid]) for gid in range(g)]
    fp = [set() for _ in range(g)]
    for t in tasks:
        fp[t[1]] |= set(topo.foots[t[0]])
    caps = [0] * n
    for gid in range(g):
        for x in fp[gid]:
            caps[x] += quota[gid]
    txs = []
    for _ in range(rng.randint(1, 12)):
        edits = []
        for _ in range(rng.randint(1, 5)):
            kind = rng.choice(['weight', 'quota', 'cap', 'move', 'bind', 'class', 'budget', 'pin'])
            if kind == 'weight':
                edits.append(['weight', rng.randrange(d), rng.randint(1, 3)])
            elif kind == 'quota':
                edits.append(['quota', rng.randrange(g), rng.choice([1, 2, 3, 0, 64])])
            elif kind == 'cap':
                edits.append(['cap', rng.randrange(n), rng.randint(0, 300)])
            elif kind == 'move':
                edits.append(['move', rng.randrange(d), rng.randrange(g)])
            elif kind == 'bind':
                edits.append(['bind', rng.randrange(d), rng.randrange(tcount)])
            elif kind == 'class':
                edits.append(['class', rng.randrange(d), rng.choice([0, 1])])
            elif kind == 'budget':
                edits.append(['budget', rng.randrange(g), rng.choice([1, 2, 10 ** 12])])
            else:
                edits.append(['pin', rng.randrange(d), rng.randint(0, 1)])
        txs.append({'revision': 0, 'edits': edits,
                    'query': {'groups': [rng.randrange(g) for _ in range(3)],
                              'nodes': [rng.randrange(n) for _ in range(4)],
                              'tasks': [rng.randrange(d) for _ in range(3)]}})
    return {'topology': spec, 'caps': caps, 'groups': [[quota[i], budget[i]] for i in range(g)],
            'tasks': tasks, 'query': {'groups': list(range(g)), 'nodes': list(range(n)),
                                      'tasks': list(range(d))}, 'transactions': txs}

SCENARIOS = {'pinned': scenario_pinned, 'empty': scenario_empty, 'tight': scenario_tight}

def build_scenario_request(seed, names=('pinned', 'empty', 'tight'), per=3):
    rng = random.Random(seed)
    sessions = []
    for _ in range(per):
        name = rng.choice(list(names))
        sessions.append(SCENARIOS[name](rng))
    return {'version': 2, 'sessions': sessions}
